{
  "states": [
    "LISTEN",
    "RESPOND",
    "REQUEST",
    "PARTOPEN",
    "OPEN",
    "CLOSEREQ",
    "CLOSING",
    "TIMEWAIT",
    "CLOSED"
  ],
  "transitions": [
    {
      "from": "LISTEN",
      "event": "rcv Request",
      "action": "Generate Response",
      "to": "RESPOND"
    },
    {
      "from": "LISTEN",
      "event": "rcv Request with Init Cookie",
      "action": "Generate new socket, switch to RESPOND",
      "to": "RESPOND"
    },
    {
      "from": "LISTEN",
      "event": "",
      "action": "Generate Reset(No Connection)",
      "to": "CLOSED"
    },
    {
      "from": "RESPOND",
      "event": "rcv Ack/DataAck",
      "action": "Leave RESPOND for OPEN",
      "to": "OPEN"
    },
    {
      "from": "RESPOND",
      "event": "timeout >= 4MSL",
      "action": "Generate Reset(Aborted)",
      "to": "CLOSED"
    },
    {
      "from": "REQUEST",
      "event": "rcv Response",
      "action": "Set sequence number variables, continue processing",
      "to": "PARTOPEN"
    },
    {
      "from": "REQUEST",
      "event": "rcv Reset",
      "action": "Set sequence number variables, continue processing",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "rcv packet (not Response/Reset/Sync)",
      "action": "Leave PARTOPEN for OPEN",
      "to": "OPEN"
    },
    {
      "from": "OPEN",
      "event": "server active close snd CloseReq",
      "action": "Move to CLOSEREQ",
      "to": "CLOSEREQ"
    },
    {
      "from": "OPEN",
      "event": "active close or rcv CloseReq",
      "action": "snd Close",
      "to": "CLOSING"
    },
    {
      "from": "CLOSEREQ",
      "event": "rcv Close",
      "action": "Move to CLOSED",
      "to": "CLOSED"
    },
    {
      "from": "CLOSEREQ",
      "event": "rcv Reset",
      "action": "Move to TIMEWAIT",
      "to": "TIMEWAIT"
    },
    {
      "from": "CLOSING",
      "event": "rcv Reset",
      "action": "Move to TIMEWAIT",
      "to": "TIMEWAIT"
    },
    {
      "from": "CLOSING",
      "event": "2MSL timer expires",
      "action": "Move to CLOSED",
      "to": "CLOSED"
    },
    {
      "from": "TIMEWAIT",
      "event": "2MSL timer expires",
      "action": "Move to CLOSED",
      "to": "CLOSED"
    }
  ]
}

{
  "states": [
    "REQUEST",
    "PARTOPEN",
    "RESPOND",
    "OPEN",
    "CLOSING",
    "TIMEWAIT"
  ],
  "transitions": [
    {
      "from": "REQUEST",
      "event": "Response",
      "action": "S.state := PARTOPEN; Set PARTOPEN timer",
      "to": "PARTOPEN"
    },
    {
      "from": "RESPOND",
      "event": "Request",
      "action": "Send Response, possibly containing Init Cookie; Destroy S and return",
      "to": "TIMEWAIT"
    },
    {
      "from": "RESPOND",
      "event": "",
      "action": "S.OSR := P.seqno; S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "Response",
      "action": "Send Ack",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "",
      "action": "S.OSR := P.seqno; S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "RESPOND",
      "event": "CloseReq",
      "action": "Generate Close; S.state := CLOSING; Set CLOSING timer",
      "to": "CLOSING"
    }
  ]
}
